UPDATE UpgradeTypes SET DisplayOrder = DisplayOrder + 1 WHERE AreaId = 4 AND DisplayOrder >= 5 AND NOT EXISTS (SELECT 1 FROM sqlite_master WHERE name = 'Fh2wheels');
INSERT OR IGNORE INTO UpgradeTypes (id, PartEnum, AreaId, IsException, DisplayOrder, EverymanUpgradeDisplayOrder, Name, Description, IconPath, ImagePath) SELECT 64, 43, 4, 1, 5, -1, '_&4038003874', '_&4038003875', IconPath, ImagePath FROM UpgradeTypes WHERE id = 30;

UPDATE List_SpringDamperPhysics SET MinRideHeight = MAX(0.02, MinRideHeight - 0.1), MaxRideHeight = MaxRideHeight + 0.4 WHERE MaxRideHeight > MinRideHeight AND NOT EXISTS (SELECT 1 FROM sqlite_master WHERE name = 'Fh2wheels');

WITH RECURSIVE sizes(inch) AS (SELECT 13 UNION ALL SELECT inch + 1 FROM sizes WHERE inch < 24) INSERT OR IGNORE INTO List_UpgradeRimSizeFront (Id, Ordinal, Level, IsStock, FrontWheelDiameter, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics) SELECT 900000000 + s.Ordinal * 100 + z.inch, s.Ordinal, CASE WHEN z.inch < s.FrontWheelDiameter THEN 100 - z.inch ELSE 30 + z.inch END, 0, z.inch, CASE WHEN z.inch < s.FrontWheelDiameter THEN 400 ELSE 1200 END, ROUND(1.36 * (z.inch - s.FrontWheelDiameter), 2), 1.0, 1.0, 0 FROM List_UpgradeRimSizeFront AS s JOIN sizes AS z ON z.inch <> s.FrontWheelDiameter WHERE s.IsStock = 1 AND NOT EXISTS (SELECT 1 FROM List_UpgradeRimSizeFront AS o WHERE o.Ordinal = s.Ordinal AND o.FrontWheelDiameter = z.inch);
