WITH RECURSIVE sizes(inch) AS (SELECT 13 UNION ALL SELECT inch + 1 FROM sizes WHERE inch < 24) INSERT OR IGNORE INTO List_UpgradeRimSizeRear (Id, Ordinal, Level, IsStock, RearWheelDiameter, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics) SELECT 900000000 + s.Ordinal * 100 + z.inch, s.Ordinal, CASE WHEN z.inch < s.RearWheelDiameter THEN 100 - z.inch ELSE 30 + z.inch END, 0, z.inch, CASE WHEN z.inch < s.RearWheelDiameter THEN 400 ELSE 1200 END, ROUND(1.36 * (z.inch - s.RearWheelDiameter), 2), 1.0, 1.0, 0 FROM List_UpgradeRimSizeRear AS s JOIN sizes AS z ON z.inch <> s.RearWheelDiameter WHERE s.IsStock = 1 AND NOT EXISTS (SELECT 1 FROM List_UpgradeRimSizeRear AS o WHERE o.Ordinal = s.Ordinal AND o.RearWheelDiameter = z.inch);
