INSERT OR IGNORE INTO List_UpgradeTireCompound (Id, Ordinal, Level, IsStock, TireCompoundID, ManufacturerID, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics, TireModelName) SELECT s.Ordinal * 1000 + 4, s.Ordinal, 4, 0, 9, 0, 10000, 0.0, 1.0, 1.0, 0, CASE WHEN s.TireModelName LIKE 'OW_%' THEN 'OW_drag' ELSE 'drag' END FROM List_UpgradeTireCompound AS s WHERE s.IsStock = 1 AND NOT EXISTS (SELECT 1 FROM List_UpgradeTireCompound AS o WHERE o.Ordinal = s.Ordinal AND o.Level = 4) AND NOT EXISTS (SELECT 1 FROM List_UpgradeTireCompound AS o WHERE o.Id = s.Ordinal * 1000 + 4);
INSERT OR IGNORE INTO List_UpgradeTireCompound (Id, Ordinal, Level, IsStock, TireCompoundID, ManufacturerID, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics, TireModelName) SELECT s.Ordinal * 1000 + 5, s.Ordinal, 5, 0, 9, 0, 10000, 0.0, 1.0, 1.0, 0, CASE WHEN s.TireModelName LIKE 'OW_%' THEN 'rallyow' ELSE 'rally' END FROM List_UpgradeTireCompound AS s WHERE s.IsStock = 1 AND NOT EXISTS (SELECT 1 FROM List_UpgradeTireCompound AS o WHERE o.Ordinal = s.Ordinal AND o.Level = 5) AND NOT EXISTS (SELECT 1 FROM List_UpgradeTireCompound AS o WHERE o.Id = s.Ordinal * 1000 + 5);

WITH RECURSIVE widths(mm) AS (SELECT 185 UNION ALL SELECT mm + 10 FROM widths WHERE mm < 395) INSERT OR IGNORE INTO List_UpgradeCarBodyTireWidthFront (Id, CarBodyId, Level, IsStock, FrontTireWidth, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics) SELECT 1000000000 + s.CarBodyId * 100 + z.mm / 10, s.CarBodyId, CASE WHEN z.mm < s.FrontTireWidth THEN 100 - z.mm / 10 ELSE 10 + z.mm / 10 END, 0, z.mm, CASE WHEN z.mm < s.FrontTireWidth THEN 400 ELSE 3000 END, ROUND(0.054 * (z.mm - s.FrontTireWidth), 2), 1.0, 1.0, 0 FROM List_UpgradeCarBodyTireWidthFront AS s JOIN widths AS z ON z.mm < s.FrontTireWidth OR z.mm > (SELECT MAX(o.FrontTireWidth) FROM List_UpgradeCarBodyTireWidthFront AS o WHERE o.CarBodyId = s.CarBodyId) WHERE s.IsStock = 1;
