WITH RECURSIVE widths(mm) AS (SELECT 185 UNION ALL SELECT mm + 10 FROM widths WHERE mm < 395) INSERT OR IGNORE INTO List_UpgradeCarBodyTireWidthRear (Id, CarBodyId, Level, IsStock, RearTireWidth, Price, MassDiff, DragScale, WindInstabilityScale, RequiresGraphics) SELECT 1000000000 + s.CarBodyId * 100 + z.mm / 10, s.CarBodyId, CASE WHEN z.mm < s.RearTireWidth THEN 100 - z.mm / 10 ELSE 10 + z.mm / 10 END, 0, z.mm, CASE WHEN z.mm < s.RearTireWidth THEN 400 ELSE 3000 END, ROUND(0.054 * (z.mm - s.RearTireWidth), 2), 1.0, 1.0, 0 FROM List_UpgradeCarBodyTireWidthRear AS s JOIN widths AS z ON z.mm < s.RearTireWidth OR z.mm > (SELECT MAX(o.RearTireWidth) FROM List_UpgradeCarBodyTireWidthRear AS o WHERE o.CarBodyId = s.CarBodyId) WHERE s.IsStock = 1;
